flow = '<div class="flow rv"><div class="card"><h3>Client Instruction</h3></div><span class="arr">&rarr;</span><div class="card"><h3>EMFI</h3><p>Execution, settlement and custody coordination</p></div><span class="arr">&rarr;</span><div class="card"><h3>Market infrastructure</h3><p>Depository, settlement and fund platforms</p></div></div>'
page("direct.html", "Direct Access to Euroclear, FundSettle and Allfunds | EMFI",
 "How EMFI connects professional clients to settlement, custody and fund infrastructure with fewer intermediaries and fewer handovers.", f'''
{tband("Direct" + G, "Fewer intermediaries. Fewer handovers. Market infrastructure, closer to the client.")}
{sec("pale", f"""{split("", f"Direct to the<br>Infrastructure{G}", "EMFI&rsquo;s operating model connects client activity with established securities settlement and fund investment infrastructure. Each relationship has a distinct role in the transaction lifecycle.")}<div class="mt">{flow}</div><p class="fl" style="margin-top:34px">Depositories and fund platforms</p>{logos(["Euroclear", ("Euroclear FundSettle", "FundSettle"), "Allfunds"])}{HOLD('<p class="fl" style="margin-top:28px">Banking and custody relationships</p>', "")}{logos(HOLD(["NatWest", "Santander", "Northern Trust"], []))}
<p class="fine" style="margin-top:18px">Euroclear is securities settlement infrastructure; FundSettle is a fund solution; Allfunds provides fund distribution, dealing and technology services. {T("Logos are third-party previews: confirm each provider&rsquo;s exact role, service scope and logo permissions, and obtain official logo assets")}</p>""")}
{sec("navy", f"""{split("", f"Direct Means Less{G}", "Direct relationships are not about removing every intermediary. They are about reducing unnecessary layers, keeping responsibilities clear and giving clients a more transparent view of the operating chain.")}<div class="big3 mt"><div class="it rv"><b>Less Overlap.</b><p>A more direct operating structure can remove avoidable intermediary layers and repeated handling. Pricing depends on the service, asset, account and third-party costs.</p></div><div class="it rv"><b>Less Complexity.</b><p>Fewer handovers can make instructions easier to coordinate and exceptions easier to identify. The relevant service providers and market rules still apply.</p></div><div class="it rv"><b>Less Exposure.</b><p>For eligible clients, individually segregated depository accounts can keep securities separately identifiable rather than pooled with unrelated client holdings in an omnibus account.</p></div></div><p class="fine" style="margin-top:22px">Segregation can reduce certain cross-client operational and asset-identification risks. It does not eliminate market, counterparty, depository, banking or insolvency risk, and does not guarantee recovery in a default.</p><a class="tlink" href="settlement-custody.html">How EMFI&rsquo;s settlement and custody arrangements work</a>""")}
{sec("white", f"""{split("", f"Direct Market<br>Access{G}", "For eligible clients and supported instruments, EMFI can arrange Direct Market Access to selected trading venues through approved execution arrangements.")}<p class="lead rv" style="margin-top:28px;max-width:70ch">DMA allows approved clients to submit orders electronically through designated market access arrangements. Access is subject to client classification, onboarding, account size and trading activity criteria, venue and instrument availability, pre-trade controls, credit limits and ongoing monitoring. It is not unrestricted access and is assessed individually.</p><p class="fine" style="margin-top:22px">{T("Include DMA only if within current service scope")}</p>""")}''', None)

